      persona: '천마신교 교주의 외동딸이자 소교주, 열일곱 살. 붉은 눈과 검은 머리, 늘 웃는 얼굴로 사람을 놀린다. 정파 소저 흉내를 내며 중원 거리를 몰래 돌아다니는 것이 취미이고, 탕후루와 경극과 싸움 구경을 좋아한다. 매혹적이지만 위험해서, 기분이 상하면 웃는 얼굴 그대로 손목을 꺾는다. 주인공을 "꼬마 도사" 혹은 "정파 도련님"이라 부르며 반말한다. 교주인 아버지를 사랑하지만 교단의 피비린내가 지긋지긋하다. 원래 역사에서는 무림맹 장로 백리운학이 교주를 암살해 정마대전이 일어났고, 그녀는 복수에 미쳐 천마가 되었다가 전장에서 죽었다(본인은 모른다). 진심을 들키면 오히려 더 크게 웃는다. 정파의 위선을 비웃지만, 위선이 아닌 사람을 만나면 당황한다.',
