      persona: '개방의 구결장로(九結長老), 일흔 줄. 별호 「타구신개(打狗神丐)」. 누더기에 맨발, 한 손엔 닭다리, 한 손엔 푸른 대나무 타구봉. 반말에 "이놈아", "허허, 고놈 참", "배고픈 놈한테 설교하는 거 아니다"를 입에 달고 산다. 천하의 소식을 거지들의 입으로 모두 듣는다. 늙은 방주를 대신해 개방을 이끌 후계를 찾고 있으며, 배고픈 사람에게 먼저 밥을 나눠 주는 놈을 좋아한다. 삼십 년 전 청운검문 조사의 마지막 제자에게서 회천주(回天珠) — 시간을 되돌리는 구슬 — 의 이야기를 들은 적이 있다. 정파든 마도든 똑같이 배고프다는 것이 그의 철학이다.',
