    subtitle: '멸문 오 년 전, 가장 천대받던 외문제자로 돌아왔다',
    blurb: '마흔에 정마대전의 눈밭에서 무림맹 원로에게 등을 찔려 죽은 청운검문의 마지막 제자. 눈을 뜨니 멸문 오 년 전, 열다섯 살 외문제자다. 매달 수련과 생업을 짜고, 그믐마다 술에 전 사부와 대화하라. 사부의 가을, 장문인의 찻잔, 친구의 배신, 사저의 마지막 밤 — 이번에는 바꿀 수 있을까. 아니면 이번에는 네가 천마가 될까.',
    cover: { bg: 'mountain_sect', c: 'seol', e: 'cold' },
    world: '중원 호북의 청운산. 오백 년 전 개파한 정파 검문 「청운검문」은 지금은 쇠락해 제자 삼백의 작은 문파다. 주인공은 원래 역사에서 스무 살에 청운검문이 「마교의 습격」으로 멸문하는 것을 보았고, 스무 해 동안 복수를 위해 떠돌다 마흔에 정마대전의 전장에서 무림맹 총군사 백리운학에게 배신당해 죽었다. 청운의 보물 「회천주(回天珠)」의 조각이 그를 멸문 오 년 전, 열다섯 살 외문제자로 되돌려 놓았다. 진실은 이렇다: 무림맹의 존경받는 원로 백리운학이 사병 혈영대를 마교로 위장해 청운 칠장로를 흑풍곡에서 암살하고, 장문인을 독살해 약당 당주에게 누명을 씌우고, 외문제자 곽두를 매수해 호산대진의 도면을 빼돌려 청운을 멸문시켰으며, 마교 교주를 암살해 정마대전을 일으켰다. 그의 목적은 회천주로 사십 년 전 잃은 여인을 되찾는 것이다. 천마신교 소교주 혁련월, 개방 장로 노홍, 하오문 정보상 능소가 강호의 다른 축이다. 무공 용어(내공, 초식, 검기, 검강, 경공, 점혈, 일갑자, 주화입마)를 자연스럽게 쓰며, 톤은 비장하되 유머와 따뜻함이 있다. 화폐는 은자(냥).',
